/// If every complex in `arr` has an imaginary part `|imag| <= tol * ε`
/// (with ε = 2), returns a new Vec where each imaginary part is set to zero;
/// otherwise returns the original Vec unchanged.
pub fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Machine epsilon as given in the problem statement.
    const MACHINE_EPS: i32 = 2;

    // Compute the threshold = tol * MACHINE_EPS, using saturating_mul for safety.
    let threshold = tol.saturating_mul(MACHINE_EPS);

    // Check if all imaginary parts are within ±threshold.
    let all_close = arr.iter().all(|c| c.imag.abs() <= threshold);

    if all_close {
        // Map each complex number to one with same real, imag = 0.
        arr.into_iter()
            .map(|c| Complex::new(c.real, 0))
            .collect()
    } else {
        // Return the original array unchanged.
        arr
    }
}

